/**
 * MAIN-world listener for successful GET /ic-web/reserve responses generated by
 * the official page. The browser's original request and response remain intact.
 * Only the limited seat projection below crosses the world boundary.
 */

const OFFICIAL_ORIGIN = 'https://seats.dlmu.edu.cn';
const TARGET_PATH = '/ic-web/reserve';
const MAX_BODY = 4 * 1024 * 1024;
const MAX_SEATS = 2000;
const MAX_INTERVALS_PER_SEAT = 1000;
const BUFFER_MAX = 3;
const BUFFER_TTL_MS = 30_000;
const CHANNEL = 'lsa:reserve-response';
const WANT_CHANNEL = 'lsa:want-buffer';
const READY_CHANNEL = 'lsa:reserve-observer-ready';

type Transport = 'XHR' | 'FETCH';
type Route = string | null;
interface RouteContext {
  route: Route;
  generation: number;
}
interface Observation extends RouteContext {
  at: string;
  captureId: number;
  transport: Transport;
}
type Payload = {body: string}
  | {httpStatus: 401 | 403}
  | {observationError: 'INVALID_RESPONSE' | 'BODY_TOO_LARGE'};
type ReserveEntry = Omit<Observation, 'generation'> & {url: string} & Payload;

const buffer: ReserveEntry[] = [];
const transports: Transport[] = [];
let route: Route = null;
let routeGeneration = 0;
let nextCaptureId = 0;
let lastPublishedId = 0;

function sanitizeRoute(hash: string): Route {
  const pathname = hash.split('?')[0];
  return /^#\/ic\/seatPredetermine\/\d{1,24}$/.test(pathname) ? pathname : null;
}

function updateRoute(next: Route): void {
  if (next === route) return;
  route = next;
  routeGeneration += 1;
  buffer.length = 0;
}

function routeContext(): RouteContext {
  updateRoute(sanitizeRoute(location.hash || ''));
  return {route, generation: routeGeneration};
}

function isCurrent(context: RouteContext): boolean {
  const current = routeContext();
  return context.route === current.route && context.generation === current.generation;
}

function isTargetUrl(url: string, base?: string): boolean {
  try {
    const parsed = new URL(url, base);
    return parsed.origin === OFFICIAL_ORIGIN
      && parsed.pathname === TARGET_PATH
      && !parsed.username && !parsed.password;
  } catch {
    return false;
  }
}

function requestBase(): string {
  return typeof document === 'undefined' ? location.origin : document.baseURI;
}

function object(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function copyScalarFields(row: Record<string, unknown>, fields: readonly string[]): Record<string, unknown> {
  const selected: Record<string, unknown> = {};
  for (const key of fields) {
    if (!Object.hasOwn(row, key)) continue;
    const value = row[key];
    if (value === null || typeof value === 'boolean'
      || typeof value === 'number' && Number.isFinite(value)
      || typeof value === 'string' && value.length <= 128 && !/[\u0000-\u001f\u007f]/.test(value)) {
      selected[key] = value;
    }
  }
  return selected;
}

function sanitizeRows(raw: unknown): unknown[] | null {
  if (!Array.isArray(raw)) return null;
  if (raw.length > MAX_SEATS) throw new Error('Seat count exceeds limit');
  return raw.map(value => {
    const row = object(value);
    if (!row) return null;
    const selected = copyScalarFields(row, [
      'devId', 'devName', 'roomId', 'roomName', 'coordinate', 'devStatus',
      'openState', 'openStart', 'openEnd', 'onlyView',
    ]);
    if (Array.isArray(row.resvInfo)) {
      if (row.resvInfo.length > MAX_INTERVALS_PER_SEAT) throw new Error('Interval count exceeds limit');
      selected.resvInfo = row.resvInfo.map(interval => {
        const entry = object(interval);
        return entry ? copyScalarFields(entry, ['startTime', 'endTime', 'resvStatus']) : null;
      });
    } else if (row.resvInfo === null) {
      selected.resvInfo = null;
    } else if (Object.hasOwn(row, 'resvInfo')) {
      // Retain the malformed-field distinction without forwarding an unknown object.
      selected.resvInfo = false;
    }
    return selected;
  });
}

function sanitizeBody(text: string): string | null {
  try {
    const raw: unknown = JSON.parse(text);
    if (Array.isArray(raw)) return JSON.stringify(sanitizeRows(raw));
    const root = object(raw);
    if (!root) return null;
    const rows = sanitizeRows(root.data);
    const nested = rows === null ? sanitizeRows(object(root.data)?.data) : null;
    if (rows === null && nested === null) return null;
    const safe: Record<string, unknown> = {};
    if (typeof root.code === 'number' && Number.isFinite(root.code)
      || typeof root.code === 'string' && /^-?\d{1,20}$/.test(root.code)) safe.code = root.code;
    safe.data = rows ?? {data: nested};
    return JSON.stringify(safe);
  } catch {
    return null;
  }
}

function emit(entry: ReserveEntry): void {
  try {
    window.postMessage({channel: CHANNEL, ...entry}, location.origin);
  } catch {
    // Observation must remain independent of page behavior.
  }
}

function beginObservation(context: RouteContext, transport: Transport): Observation | null {
  if (!isCurrent(context)) return null;
  return {...context, at: new Date().toISOString(), captureId: ++nextCaptureId, transport};
}

function publish(observation: Observation, payload: Payload): void {
  if (!isCurrent(observation) || observation.captureId <= lastPublishedId) return;
  lastPublishedId = observation.captureId;
  const {at, captureId, transport, route: requestRoute} = observation;
  const entry: ReserveEntry = {url: TARGET_PATH, at, captureId, transport, route: requestRoute, ...payload};
  buffer.push(entry);
  if (buffer.length > BUFFER_MAX) buffer.shift();
  emit(entry);
}

function publishBody(observation: Observation, body: string | null): void {
  if (body === null || body.length > MAX_BODY) {
    publish(observation, {observationError: 'BODY_TOO_LARGE'});
    return;
  }
  if (!isCurrent(observation) || observation.captureId <= lastPublishedId) return;
  const safe = sanitizeBody(body);
  publish(observation, safe === null ? {observationError: 'INVALID_RESPONSE'} : {body: safe});
}

function patchXhr(): void {
  const proto = XMLHttpRequest.prototype;
  const originalOpen = proto.open;
  const originalSend = proto.send;
  const requests = new WeakMap<XMLHttpRequest, {listener?: EventListener}>();

  proto.open = function (this: XMLHttpRequest, method: string, url: string | URL) {
    const previous = requests.get(this);
    const result = originalOpen.apply(this, arguments as never);
    try {
      if (previous?.listener) this.removeEventListener('load', previous.listener);
      requests.delete(this);
      if (typeof method === 'string' && method.toUpperCase() === 'GET'
        && (typeof url === 'string' || url instanceof URL)
        && isTargetUrl(String(url), requestBase())) {
        requests.set(this, {});
      }
    } catch {
      requests.delete(this);
    }
    return result;
  } as typeof proto.open;

  proto.send = function (this: XMLHttpRequest) {
    const request = requests.get(this);
    if (!request || request.listener) return originalSend.apply(this, arguments as never);
    const context = routeContext();
    const listener: EventListener = event => {
      if (event.isTrusted === false) return;
      request.listener = undefined;
      try {
        this.removeEventListener('load', listener);
        if (requests.get(this) !== request || !isTargetUrl(this.responseURL)) return;
        const status = this.status;
        if (!Number.isInteger(status) || status !== 401 && status !== 403 && (status < 200 || status >= 300)) return;
        const observation = beginObservation(context, 'XHR');
        if (!observation) return;
        if (status === 401 || status === 403) {
          publish(observation, {httpStatus: status});
        } else if (this.responseType === '' || this.responseType === 'text') {
          publishBody(observation, this.responseText);
        }
      } catch {
        // A read failure cannot change the result seen by the page.
      }
    };
    try {
      this.addEventListener('load', listener);
      request.listener = listener;
    } catch {
      return originalSend.apply(this, arguments as never);
    }
    try {
      return originalSend.apply(this, arguments as never);
    } catch (error) {
      try { this.removeEventListener('load', listener); } catch { /* Preserve original error. */ }
      request.listener = undefined;
      throw error;
    }
  } as typeof proto.send;
}

function fetchTarget(input: RequestInfo | URL, init?: RequestInit): boolean {
  let url: string;
  let method = 'GET';
  if (typeof input === 'string') {
    url = input;
  } else if (input instanceof URL) {
    url = input.href;
  } else if (input instanceof Request) {
    url = input.url;
    method = input.method;
  } else {
    return false;
  }
  if (init) {
    const prototype = Object.getPrototypeOf(init);
    if (prototype !== Object.prototype && prototype !== null) return false;
    const descriptor = Object.getOwnPropertyDescriptor(init, 'method');
    if (descriptor && !('value' in descriptor)) return false;
    if (descriptor?.value !== undefined) {
      if (typeof descriptor.value !== 'string') return false;
      method = descriptor.value;
    }
  }
  return method.toUpperCase() === 'GET' && isTargetUrl(url, requestBase());
}

async function readBoundedBody(response: Response): Promise<string | null> {
  if (Number(response.headers.get('Content-Length')) > MAX_BODY) return null;
  const reader = response.clone().body?.getReader();
  if (!reader) return '';
  const decoder = new TextDecoder();
  const parts: string[] = [];
  let bytes = 0;
  try {
    while (true) {
      const {done, value} = await reader.read();
      if (done) break;
      bytes += value.byteLength;
      if (bytes > MAX_BODY) {
        // Do not await cancellation of a tee: the page's original branch can still be reading.
        void reader.cancel().catch(() => {});
        return null;
      }
      parts.push(decoder.decode(value, {stream: true}));
    }
    parts.push(decoder.decode());
    return parts.join('');
  } finally {
    reader.releaseLock();
  }
}

function patchFetch(): void {
  const originalFetch = window.fetch;
  window.fetch = function (this: unknown, input: RequestInfo | URL, init?: RequestInit) {
    const context = routeContext();
    const result = originalFetch.apply(this, arguments as never);
    try {
      if (fetchTarget(input, init)) {
        void result.then(response => {
          if (!isTargetUrl(response.url)) return;
          const status = response.status;
          if (!response.ok && status !== 401 && status !== 403) return;
          const observation = beginObservation(context, 'FETCH');
          if (!observation) return;
          if (status === 401 || status === 403) {
            publish(observation, {httpStatus: status});
            return;
          }
          return readBoundedBody(response).then(
            body => publishBody(observation, body),
            () => publish(observation, {observationError: 'INVALID_RESPONSE'}),
          );
        }).catch(() => {});
      }
    } catch {
      // Inspection failure does not change the returned fetch promise.
    }
    return result;
  } as typeof window.fetch;
}

function install(): void {
  if (location.origin !== OFFICIAL_ORIGIN) return;
  routeContext();
  window.addEventListener('hashchange', event => {
    try {
      updateRoute(sanitizeRoute(new URL(event.newURL).hash));
    } catch {
      routeContext();
    }
  });
  window.addEventListener('popstate', () => { routeContext(); });
  window.addEventListener('pagehide', () => {
    routeGeneration += 1;
    buffer.length = 0;
  });
  window.addEventListener('message', event => {
    if (event.source !== window || event.origin !== OFFICIAL_ORIGIN || event.data?.channel !== WANT_CHANNEL) return;
    const context = routeContext();
    try {
      window.postMessage({
        channel: READY_CHANNEL,
        at: new Date().toISOString(),
        transports: transports.slice(),
      }, OFFICIAL_ORIGIN);
    } catch {
      return;
    }
    const now = Date.now();
    for (const entry of buffer) {
      const age = now - Date.parse(entry.at);
      if (entry.route === context.route && age >= 0 && age < BUFFER_TTL_MS) emit(entry);
    }
  });
  try {
    patchXhr();
    transports.push('XHR');
  } catch {
    // Other transports can still be available.
  }
  if (typeof window.fetch === 'function') {
    try {
      patchFetch();
      transports.push('FETCH');
    } catch {
      // No page request is needed to verify availability of the hook.
    }
  }
}

try {
  install();
} catch {
  // Extension initialization cannot block the host page.
}

export {};
